  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Ondansetron absolute oral bioavailability was 0.56 (0.52-0.62) in healthy young volunteers after 8 mg oral vs IV, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Nevirapine absolute oral bioavailability was 91 ± 8% in healthy male volunteers after a 50 mg oral solution vs 15 mg IV infusion, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Didanosine overall absolute bioavailability was approximately 43% in patients using IV reference data, above the 20% threshold; lower values were condition-specific and not the strongest ordinary-condition record.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All supplied evidence molecules support high oral bioavailability at the F≥20% threshold. Numeric absolute F values in ordinary conditions range from about 43% to 100%, with no ordinary-condition record below 20%; condition-specific low values are discounted.",
  "evidence_gaps": [
    "Sub-20% values are limited to altered conditions such as didanosine with food or antacid solution; no ordinary-condition absolute F below 20% was supplied.",
    "Some records are qualitative or use non-absolute bioavailability report types, but they are corroborated by numeric absolute measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

